1	<script lang="ts">
2		/**
3		 * Receipt Image Viewer Component
4		 *
5		 * Provides zoom and pan capabilities for receipt images in a floating modal.
6		 * Implements specifications #{#zom1a} through #{#zom5b} from
7		 * specs/specifications/receipt-image-zoom-pan.md
8		 *
9		 * Zoom anchors to cursor position (mouse wheel, pinch midpoint, double-tap).
10		 * Scrollable container replaces manual pan — native scrollbars + drag-to-scroll.
11		 *
12		 * @component
13		 */
14	
15		import {
16			MIN_ZOOM,
17			ZOOM_STEP,
18			DOUBLE_TAP_ZOOM,
19			VIEWPORT_FRACTION,
20			calculateFitDimensions,
21			calculateMaxZoom
22		} from '$lib/utils/imageZoom';
23	
24		// Props — #{#pdf1a} added isPdf for PDF detection
25		interface Props {
26			imageUrl: string;
27			altText?: string;
28			show?: boolean;
29			isPdf?: boolean;
30			onclose?: () => void;
31		}
32	
33		let {
34			imageUrl,
35			altText = 'Receipt image',
36			show = false,
37			isPdf = false,
38			onclose
39		}: Props = $props();
40	
41		// Zoom state - #{#zom1a}
42		let zoom = $state(100);
43	
44		// Drag-to-scroll state - #{#zom2a}
45		let isDragging = $state(false);
46		let dragStartX = $state(0);
47		let dragStartY = $state(0);
48		let scrollStartX = $state(0);
49		let scrollStartY = $state(0);
50	
51		// Touch gesture state - #{#zom3a}
52		let touchStartDistance = $state(0);
53		let touchStartZoom = $state(100);
54		let lastTapTime = $state(0);
55	
56		// Image base dimensions (fit-to-viewport at 100%)
57		let baseWidth = $state(0);
58		let baseHeight = $state(0);
59	
60		// The image's own resolution, which sets how far it can honestly be zoomed
61		let naturalWidth = $state(0);
62	
63		// Refs
64		let scrollContainer: HTMLDivElement | undefined = $state(undefined);
65	
66		// Constants
67		const PAN_STEP = 50;
68		const DOUBLE_TAP_DELAY = 300; // ms
69	
70		/**
71		 * The zoom ceiling is a property of THIS image, not a fixed percentage: it is
72		 * the point where one image pixel fills one CSS pixel. Beyond it the browser
73		 * would only interpolate, so the controls stop there — and for an image
74		 * already at or under viewport size they never leave 100% at all.
75		 */
76		let maxZoom = $derived(calculateMaxZoom(naturalWidth, baseWidth));
77	
78		/**
79		 * The box that clips the scroll container. It has to describe the same area
80		 * `handleImageLoad` fits into, since that area is what 100% means.
81		 */
82		const viewportBox = `max-width: ${VIEWPORT_FRACTION.width * 100}vw; max-height: ${VIEWPORT_FRACTION.height * 100}vh;`;
83	
84		// Pending scroll adjustment for zoom-to-cursor
85		let rafId = 0;
86	
87		// Computed scaled dimensions
88		let scaledWidth = $derived((baseWidth * zoom) / 100);
89		let scaledHeight = $derived((baseHeight * zoom) / 100);
90	
91		/**
92		 * Capture base dimensions on image load — the size the image
93		 * occupies at 100% zoom, fit within the viewport constraints.
94		 */
95		function handleImageLoad(e: Event) {
96			const img = e.target as HTMLImageElement;
97			naturalWidth = img.naturalWidth;
98			const fit = calculateFitDimensions(
99				img.naturalWidth,
100				img.naturalHeight,
101				window.innerWidth * VIEWPORT_FRACTION.width,
102				window.innerHeight * VIEWPORT_FRACTION.height
103			);
104			baseWidth = fit.width;
105			baseHeight = fit.height;
106		}
107	
108		/**
109		 * #{#zom1a} Zoom to a specific level, optionally anchored at a cursor position.
110		 * The point under the cursor stays fixed on screen after zoom.
111		 */
112		function zoomTo(newZoom: number, cursorX?: number, cursorY?: number) {
113			const container = scrollContainer;
114			newZoom = Math.max(MIN_ZOOM, Math.min(maxZoom, newZoom));
115	
116			if (!container || baseWidth === 0) {
117				zoom = newZoom;
118				return;
119			}
120	
121			const oldZoom = zoom;
122			if (newZoom === oldZoom) return;
123	
124			const rect = container.getBoundingClientRect();
125			// Default to center of viewport if no cursor position given
126			const cx = cursorX !== undefined ? cursorX - rect.left : rect.width / 2;
127			const cy = cursorY !== undefined ? cursorY - rect.top : rect.height / 2;
128	
129			// Point in base-image coordinates under the cursor
130			const imageX = (container.scrollLeft + cx) / (oldZoom / 100);
131			const imageY = (container.scrollTop + cy) / (oldZoom / 100);
132	
133			zoom = newZoom;
134	
135			// After Svelte updates the DOM (image resizes), adjust scroll so the
136			// same image point remains under the cursor.
137			const targetScrollLeft = imageX * (newZoom / 100) - cx;
138			const targetScrollTop = imageY * (newZoom / 100) - cy;
139			cancelAnimationFrame(rafId);
140			rafId = requestAnimationFrame(() => {
141				if (container) {
142					container.scrollLeft = targetScrollLeft;
143					container.scrollTop = targetScrollTop;
144				}
145			});
146		}
147	
148		/**
149		 * #{#zom1a} Zoom in by one step (snaps to 50% increments)
150		 *
151		 * The ceiling is rarely a multiple of ZOOM_STEP; `zoomTo` clamps, so the last
152		 * step lands on the ceiling itself rather than overshooting or being skipped.
153		 */
154		function zoomIn(cursorX?: number, cursorY?: number) {
155			zoomTo(Math.ceil((zoom + 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
156		}
157	
158		/**
159		 * #{#zom1a} Zoom out by one step (snaps to 50% increments)
160		 */
161		function zoomOut(cursorX?: number, cursorY?: number) {
162			zoomTo(Math.floor((zoom - 1) / ZOOM_STEP) * ZOOM_STEP, cursorX, cursorY);
163		}
164	
165		/**
166		 * #{#zom1a} Reset zoom to 100% and scroll to origin
167		 */
168		function resetZoom() {
169			zoom = MIN_ZOOM;
170			if (scrollContainer) {
171				scrollContainer.scrollLeft = 0;
172				scrollContainer.scrollTop = 0;
173			}
174		}
175	
176		/**
177		 * #{#zom1b} #{#pdf1c} Handle mouse wheel zoom — disabled for PDFs.
178		 * Zooms toward the cursor position.
179		 */
180		function handleWheel(e: WheelEvent) {
181			if (isPdf) return; // #{#pdf1c} Let browser PDF viewer handle scroll
182			e.preventDefault();
183			if (e.deltaY < 0) {
184				zoomIn(e.clientX, e.clientY);
185			} else {
186				zoomOut(e.clientX, e.clientY);
187			}
188		}
189	
190		/**
191		 * #{#zom2a} #{#pdf1c} Handle mouse down to start drag-scrolling — disabled for PDFs
192		 */
193		function handleMouseDown(e: MouseEvent) {
194			if (isPdf) return; // #{#pdf1c}
195			if (zoom > MIN_ZOOM) {
196				isDragging = true;
197				dragStartX = e.clientX;
198				dragStartY = e.clientY;
199				scrollStartX = scrollContainer?.scrollLeft ?? 0;
200				scrollStartY = scrollContainer?.scrollTop ?? 0;
201				e.preventDefault();
202			}
203		}
204	
205		/**
206		 * #{#zom2a} Handle mouse move for drag-scrolling
207		 */
208		function handleMouseMove(e: MouseEvent) {
209			if (isDragging && scrollContainer) {
210				scrollContainer.scrollLeft = scrollStartX - (e.clientX - dragStartX);
211				scrollContainer.scrollTop = scrollStartY - (e.clientY - dragStartY);
212			}
213		}
214	
215		/**
216		 * #{#zom2a} Handle mouse up to stop drag-scrolling
217		 */
218		function handleMouseUp() {
219			isDragging = false;
220		}
221	
222		/**
223		 * #{#zom2b} #{#zom5a} #{#pdf1c} Handle keyboard navigation — zoom/pan disabled for PDFs
224		 */
225		function handleKeydown(e: KeyboardEvent) {
226			// Only handle keyboard shortcuts when the image viewer is open
227			if (!show) return;
228	
229			// Escape key closes modal - #{#zom5a} — works for both images and PDFs
230			if (e.key === 'Escape') {
231				close();
232				return;
233			}
234	
235			// #{#pdf1c} Skip zoom/pan keyboard shortcuts for PDFs
236			if (isPdf) return;
237	
238			// Arrow keys for scrolling when zoomed - #{#zom2b}
239			if (zoom > MIN_ZOOM && scrollContainer) {
240				switch (e.key) {
241					case 'ArrowUp':
242						scrollContainer.scrollTop -= PAN_STEP;
243						e.preventDefault();
244						break;
245					case 'ArrowDown':
246						scrollContainer.scrollTop += PAN_STEP;
247						e.preventDefault();
248						break;
249					case 'ArrowLeft':
250						scrollContainer.scrollLeft -= PAN_STEP;
251						e.preventDefault();
252						break;
253					case 'ArrowRight':
254						scrollContainer.scrollLeft += PAN_STEP;
255						e.preventDefault();
256						break;
257				}
258			}
259	
260			// Optional keyboard shortcuts for zoom - #{#zom2b}
261			if (e.key === '+' || e.key === '=') {
262				zoomIn();
263				e.preventDefault();
264			} else if (e.key === '-') {
265				zoomOut();
266				e.preventDefault();
267			} else if (e.key === '0') {
268				resetZoom();
269				e.preventDefault();
270			}
271		}
272	
273		/**
274		 * #{#zom3a} Calculate distance between two touch points
275		 */
276		function getTouchDistance(e: TouchEvent): number {
277			if (e.touches.length < 2) return 0;
278			const touch1 = e.touches[0];
279			const touch2 = e.touches[1];
280			const dx = touch1.clientX - touch2.clientX;
281			const dy = touch1.clientY - touch2.clientY;
282			return Math.sqrt(dx * dx + dy * dy);
283		}
284	
285		/**
286		 * #{#zom3a} Get midpoint between two touch points
287		 */
288		function getTouchMidpoint(e: TouchEvent): { x: number; y: number } {
289			return {
290				x: (e.touches[0].clientX + e.touches[1].clientX) / 2,
291				y: (e.touches[0].clientY + e.touches[1].clientY) / 2
292			};
293		}
294	
295		/**
296		 * #{#zom3a} #{#pdf1c} Handle touch start for pinch zoom and pan — disabled for PDFs
297		 */
298		function handleTouchStart(e: TouchEvent) {
299			if (isPdf) return; // #{#pdf1c}
300			if (e.touches.length === 2) {
301				// Pinch zoom start
302				touchStartDistance = getTouchDistance(e);
303				touchStartZoom = zoom;
304				e.preventDefault();
305			} else if (e.touches.length === 1) {
306				// Check for double tap - #{#zom3a}
307				const now = Date.now();
308				if (now - lastTapTime < DOUBLE_TAP_DELAY) {
309					// Double tap detected — zoom toward tap point
310					if (zoom === MIN_ZOOM) {
311						zoomTo(DOUBLE_TAP_ZOOM, e.touches[0].clientX, e.touches[0].clientY);
312					} else {
313						resetZoom();
314					}
315					e.preventDefault();
316				}
317				lastTapTime = now;
318	
319				// Single touch drag-scroll (if zoomed)
320				if (zoom > MIN_ZOOM) {
321					isDragging = true;
322					dragStartX = e.touches[0].clientX;
323					dragStartY = e.touches[0].clientY;
324					scrollStartX = scrollContainer?.scrollLeft ?? 0;
325					scrollStartY = scrollContainer?.scrollTop ?? 0;
326				}
327			}
328		}
329	
330		/**
331		 * #{#zom3a} #{#pdf1c} Handle touch move for pinch zoom and pan — disabled for PDFs
332		 */
333		function handleTouchMove(e: TouchEvent) {
334			if (isPdf) return; // #{#pdf1c}
335			if (e.touches.length === 2) {
336				// Pinch zoom — anchored at midpoint between fingers
337				const currentDistance = getTouchDistance(e);
338				const mid = getTouchMidpoint(e);
339				const newZoom = touchStartZoom * (currentDistance / touchStartDistance);
340				zoomTo(newZoom, mid.x, mid.y);
341				e.preventDefault();
342			} else if (e.touches.length === 1 && isDragging && scrollContainer) {
343				// Drag to scroll
344				scrollContainer.scrollLeft = scrollStartX - (e.touches[0].clientX - dragStartX);
345				scrollContainer.scrollTop = scrollStartY - (e.touches[0].clientY - dragStartY);
346				e.preventDefault();
347			}
348		}
349	
350		/**
351		 * #{#zom3a} Handle touch end
352		 */
353		function handleTouchEnd() {
354			isDragging = false;
355			touchStartDistance = 0;
356		}
357	
358		/**
359		 * #{#zom2a} #{#zom3a} Wire the pointer/wheel/touch gestures imperatively.
360		 *
361		 * These are mouse/touch *enhancements* on a natively-scrollable container, with
362		 * full keyboard parity provided elsewhere (global arrow/zoom/Escape shortcuts on
363		 * <svelte:window> and the Tab-reachable zoom buttons). There is no ARIA role that
364		 * accurately models a custom zoom/pan surface, so attaching the listeners via an
365		 * action (rather than markup `on*` handlers) keeps the element honestly
366		 * role-less. wheel/touchstart/touchmove are registered non-passive because the
367		 * handlers call preventDefault().
368		 */
369		function gestureSurface(node: HTMLElement) {
370			const active = { passive: false } as AddEventListenerOptions;
371			node.addEventListener('wheel', handleWheel, active);
372			node.addEventListener('mousedown', handleMouseDown);
373			node.addEventListener('touchstart', handleTouchStart, active);
374			node.addEventListener('touchmove', handleTouchMove, active);
375			node.addEventListener('touchend', handleTouchEnd);
376			return {
377				destroy() {
378					node.removeEventListener('wheel', handleWheel);
379					node.removeEventListener('mousedown', handleMouseDown);
380					node.removeEventListener('touchstart', handleTouchStart);
381					node.removeEventListener('touchmove', handleTouchMove);
382					node.removeEventListener('touchend', handleTouchEnd);
383				}
384			};
385		}
386	
387		/**
388		 * #{#rim1b} Close the viewer
389		 */
390		function close() {
391			onclose?.();
392			resetZoom(); // #{#zom4a} Reset state when closing
393		}
394	
395		/**
396		 * #{#rim1b} Handle backdrop click
397		 */
398		function handleBackdropClick(e: MouseEvent) {
399			if (e.target === e.currentTarget) {
400				close();
401			}
402		}
403	
404		/**
405		 * #{#rim1b} Keyboard equivalent of the backdrop click: Escape dismisses the modal.
406		 * (Escape is also handled globally via <svelte:window>; this keeps the dialog
407		 * element's click action paired with a keyboard action for accessibility.)
408		 */
409		function handleBackdropKeydown(e: KeyboardEvent) {
410			if (e.key === 'Escape') {
411				close();
412			}
413		}
414	
415		/**
416		 * #{#zom4a} Reset state when component shows
417		 */
418		$effect(() => {
419			if (show) {
420				resetZoom();
421				baseWidth = 0;
422				baseHeight = 0;
423				naturalWidth = 0;
424			}
425		});
426	
427		/**
428		 * #{#zom2a} Compute cursor style based on zoom and drag state
429		 */
430		let cursorStyle = $derived(zoom > MIN_ZOOM ? (isDragging ? 'grabbing' : 'grab') : 'default');
431	</script>
432	
433	<svelte:window onmousemove={handleMouseMove} onmouseup={handleMouseUp} onkeydown={handleKeydown} />
434	
435	{#if show}
436		<!-- #{#zom5a} Modal with proper ARIA attributes -->
437		<div
438			class="fixed inset-0 z-60 flex items-center justify-center bg-black/90 p-4"
439			onclick={handleBackdropClick}
440			onkeydown={handleBackdropKeydown}
441			role="dialog"
442			aria-modal="true"
443			aria-labelledby="receipt-image-viewer-title"
444			tabindex="-1"
445			style="touch-action: {isPdf ? 'auto' : 'none'};"
446		>
447			<!-- #{#zom5a} Screen reader title -->
448			<h2 id="receipt-image-viewer-title" class="sr-only">Receipt Image Viewer</h2>
449	
450			<!-- #{#rim1b} Close button -->
451			<button
452				onclick={close}
453				class="absolute top-4 right-4 text-white transition-colors hover:text-gray-300"
454				aria-label="Close image viewer"
455				type="button"
456			>
457				<svg class="size-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
458					<path
459						stroke-linecap="round"
460						stroke-linejoin="round"
461						stroke-width="2"
462						d="M6 18L18 6M6 6l12 12"
463					/>
464				</svg>
465			</button>
466	
467			<!-- #{#pdf1b} PDF display with white background -->
468			{#if isPdf}
469				<div
470					class="relative flex max-h-[80vh] max-w-[90vw] items-center justify-center"
471					role="document"
472					aria-label={altText}
473				>
474					<iframe src={imageUrl} title={altText} class="h-[80vh] w-[90vw] rounded-sm bg-white"
475					></iframe>
476				</div>
477			{:else}
478				<!--
479					Scrollable image container — replaces fixed-viewport + manual pan.
480					Gestures (wheel-zoom, drag-pan, pinch) are wired via use:gestureSurface so
481					the element stays role-less; the receipt is exposed to assistive tech
482					through the inner <img alt>, and keyboard control lives on the window
483					shortcuts and the zoom buttons.
484				-->
485				<div
486					bind:this={scrollContainer}
487					class="receipt-scroll-container relative overflow-auto rounded-sm"
488					use:gestureSurface
489					style={baseWidth > 0
490						? `width: ${Math.min(scaledWidth, window.innerWidth * VIEWPORT_FRACTION.width)}px; height: ${baseHeight}px; ${viewportBox} cursor: ${cursorStyle};`
491						: `${viewportBox} cursor: ${cursorStyle};`}
492				>
493					{#if baseWidth > 0}
494						<!-- #{#rim2a} Receipt image — sized directly for natural scroll -->
495						<img
496							src={imageUrl}
497							alt={altText}
498							class="block max-w-none select-none"
499							style="width: {scaledWidth}px; height: {scaledHeight}px;"
500							draggable="false"
501							onload={handleImageLoad}
502						/>
503					{:else}
504						<!-- Initial render before dimensions are known -->
505						<img
506							src={imageUrl}
507							alt={altText}
508							class="block max-h-[80vh] max-w-[90vw] object-contain select-none"
509							draggable="false"
510							onload={handleImageLoad}
511						/>
512					{/if}
513				</div>
514			{/if}
515	
516			<!-- #{#zom1a} #{#pdf1c} Zoom controls — hidden for PDFs -->
517			{#if !isPdf}
518				<div
519					class="absolute right-8 bottom-8 flex items-center gap-2 rounded-lg bg-black/70 px-4 py-2 text-white backdrop-blur-sm"
520				>
521					<!-- Zoom out button -->
522					<button
523						onclick={() => zoomOut()}
524						disabled={zoom <= MIN_ZOOM}
525						aria-label="Zoom out"
526						class="rounded-sm p-2 transition-colors hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-30"
527						type="button"
528					>
529						<svg class="size-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
530							<path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 12H4" />
531						</svg>
532					</button>
533	
534					<!-- #{#zom5b} Current zoom percentage display -->
535					<span class="min-w-12 text-center text-sm font-medium" aria-live="polite">
536						{Math.round(zoom)}%
537					</span>
538	
539					<!-- Zoom in button -->
540					<button
541						onclick={() => zoomIn()}
542						disabled={zoom >= maxZoom}
543						aria-label="Zoom in"
544						class="rounded-sm p-2 transition-colors hover:bg-white/10 disabled:cursor-not-allowed disabled:opacity-30"
545						type="button"
546					>
547						<svg class="size-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
548							<path
549								stroke-linecap="round"
550								stroke-linejoin="round"
551								stroke-width="2"
552								d="M12 4v16m8-8H4"
553							/>
554						</svg>
555					</button>
556	
557					<!-- Divider -->
558					<div class="mx-1 h-6 w-px bg-white/30"></div>
559	
560					<!-- Reset button -->
561					<button
562						onclick={resetZoom}
563						aria-label="Reset zoom to 100%"
564						class="rounded-sm px-3 py-1 text-sm transition-colors hover:bg-white/10"
565						type="button"
566					>
567						Reset
568					</button>
569				</div>
570			{/if}
571	
572			<!-- #{#zom5a} Screen reader announcements for zoom level changes -->
573			<div class="sr-only" aria-live="polite" aria-atomic="true">
574				{isPdf ? 'Viewing PDF receipt' : `Zoom level: ${Math.round(zoom)}%`}
575			</div>
576		</div>
577	{/if}
578	
579	<style>
580		/* #{#zom5a} Screen reader only class */
581		.sr-only {
582			position: absolute;
583			width: 1px;
584			height: 1px;
585			padding: 0;
586			margin: -1px;
587			overflow: hidden;
588			clip: rect(0, 0, 0, 0);
589			white-space: nowrap;
590			border-width: 0;
591		}
592	
593		/* Subtle scrollbars for the dark modal background */
594		.receipt-scroll-container {
595			scrollbar-width: thin;
596			scrollbar-color: rgba(255, 255, 255, 0.3) transparent;
597		}
598		.receipt-scroll-container::-webkit-scrollbar {
599			width: 8px;
600			height: 8px;
601		}
602		.receipt-scroll-container::-webkit-scrollbar-track {
603			background: transparent;
604		}
605		.receipt-scroll-container::-webkit-scrollbar-thumb {
606			background: rgba(255, 255, 255, 0.3);
607			border-radius: 4px;
608		}
609		.receipt-scroll-container::-webkit-scrollbar-thumb:hover {
610			background: rgba(255, 255, 255, 0.5);
611		}
612	</style>
